// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address actor, uint96 amount) public {
        vm.assume(actor != address(0));
        uint before = c.depositsCount();
        vm.deal(actor, uint256(amount));
        vm.prank(actor);
        (bool ok,) = address(c).call{value: uint256(amount)}("");
        assertTrue(ok && c.depositsCount() == before + 1, "deposit must increment count by 1");
    }
}
